"use strict";(self.webpackChunkrithmia=self.webpackChunkrithmia||[]).push([["1057"],{295(e,t,n){n.r(t),n.d(t,{metadata:()=>r,default:()=>c,frontMatter:()=>i,contentTitle:()=>h,toc:()=>d,assets:()=>s});var r=JSON.parse('{"id":"Setting/Rithmia/Continents/Bredoa/the-dragon-empire","title":"The dragon empire","description":"Established after the Elemental War by a noble Gold Dragon, Ceolruleid, The Unhesitant Protector, who created the first mighty union between metallic, chromatic and gem dragons. All of a lawful nature they decided to create a grand empire that could withstand a great cataclysm like the ones forced upon them by the gods just 50 years beforehand. Gold (LG) Green (LE) and either emerald or ruby (LN). They believed their adherence to law could help them overcome the moral differences they shared. Three branches of government were created and each draconic group ruled over one with checks and balances between the three to ensure stability of the nation.","source":"@site/docs/Setting/Rithmia/Continents/Bredoa/the-dragon-empire.md","sourceDirName":"Setting/Rithmia/Continents/Bredoa","slug":"/Setting/Rithmia/Continents/Bredoa/the-dragon-empire","permalink":"/Rithmia/docs/Setting/Rithmia/Continents/Bredoa/the-dragon-empire","draft":false,"unlisted":false,"editUrl":"https://github.com/TravisH18/Rithmia/tree/main/docs/docs/Setting/Rithmia/Continents/Bredoa/the-dragon-empire.md","tags":[],"version":"current","frontMatter":{},"sidebar":"settingSidebar","previous":{"title":"Overview","permalink":"/Rithmia/docs/Setting/Rithmia/Continents/Bredoa/overview"},"next":{"title":"Titan jungle","permalink":"/Rithmia/docs/Setting/Rithmia/Continents/Bredoa/titan-jungle"}}'),o=n(4848),a=n(8453);let i={},h="The dragon empire",s={},d=[];function l(e){let t={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"the-dragon-empire",children:"The dragon empire"})}),"\n",(0,o.jsx)(t.p,{children:"Established after the Elemental War by a noble Gold Dragon, Ceolruleid, The Unhesitant Protector, who created the first mighty union between metallic, chromatic and gem dragons. All of a lawful nature they decided to create a grand empire that could withstand a great cataclysm like the ones forced upon them by the gods just 50 years beforehand. Gold (LG) Green (LE) and either emerald or ruby (LN). They believed their adherence to law could help them overcome the moral differences they shared. Three branches of government were created and each draconic group ruled over one with checks and balances between the three to ensure stability of the nation."}),"\n",(0,o.jsx)(t.p,{children:"LG: Gold - Executive branch"}),"\n",(0,o.jsx)(t.p,{children:"LN: Gem (Emerald or ruby) - Judicial branch"}),"\n",(0,o.jsx)(t.p,{children:"LE: Green - Legislative branch"}),"\n",(0,o.jsx)(t.p,{children:"The Founding Dragons:"}),"\n",(0,o.jsx)(t.p,{children:'Gold: Ceolruleid, The Unhesitant Protector, was one of the few ancient dragons alive at the end of the elemental war (not selected to become a deity in the elemental energy plane). As his title suggests this gold dragon not only had golden scales but a heart of gold as well. They sought the protection and happiness of all creatures no matter how much smaller than him they were. At already ~800 years old this dragon servered as the benevelant ruler of the executive branch of the empire for 400 years in which they stopped being an ancient dragon and became a Great Wyrm. This marked the end of its physical and mental development. Fearing that this would lead to stagnation and regressivism the Gold dragon had to decide between their various offspring to choose a successor. Lots of interesting stories to be told with this. Maybe the green dragon manipulates one of the offspring to gain a puppet in a second branch of government. This does not have to happen quickly as Gold dragons can live up to 4400 years baring intervention. However once a successor is chosen Ceolruleid wills its spirit to depart and "dies" but becomes a guardian of the land. Their spirit seems to permeate all edges of the empire but is strongest in the mountains surrounding the capitol.'}),"\n",(0,o.jsx)(t.p,{children:"Green: chiarrayrth, The Viridescent Viper was a young adult dragon during the founding. Unusually cunning for her age he is actually quite a hermit and would rather stay to themselves in the forest and use their intellect to hunt however after a chance encounter with Ceolruleid they found themselves oddly infatuated with the goal of \"breaking\" the gold dragon of their purely good ways and will go to great lengths to shatter the positive outlook of the gold dragon to the point where they feel they can't die happy until they've seen a broken Ceolruleid."}),"\n",(0,o.jsx)(t.p,{children:"These colors are present in the flag of the empire:"}),"\n",(0,o.jsx)(t.p,{children:"Verdant green background"}),"\n",(0,o.jsx)(t.p,{children:"Bright red sun in the upper right corner"}),"\n",(0,o.jsx)(t.p,{children:"A long golden dragon snaking from the bottom left diagonally to the top right mouth open like it is about to consume the sun"}),"\n",(0,o.jsx)(t.p,{children:"All the founding dragons serve as the head of their branch and choose their own ways of running their branch."}),"\n",(0,o.jsx)(t.p,{children:"The founding gold dragon continues to rule as the sole leader of the executive branch for centuries to come"}),"\n",(0,o.jsx)(t.p,{children:'As worthy dragons/humanoids arise who are wholly bound to the law (like sky breakers) they are appointed, two at a time, as judges so the court system has varying numbers of judges over the course of the coming centuries. With the "wisest" Gem dragon serving as the "Eternal Tie Breaker" making sure there is always an odd number of judicators.'}),"\n",(0,o.jsx)(t.p,{children:"The founding green dragon tires of ruling democratically and rules the legislative branch in secret. Allowing people to elect local leaders to be a part of the legislative branch. This branch has the largest number of members that begin infighting and disrupting the government as a whole. However the founding green dragon culls from the shadows keeping the best interest of the land over the populace of their empire."}),"\n",(0,o.jsx)(t.p,{children:"An interesting dichotomy would be the gold dragon / executive branch cares more for the people and the Green / legislative branch doesn't care for the people as much but does try to protect the jungles/forests at the expense of the people good of expanding the empire."}),"\n",(0,o.jsx)(t.p,{children:"Over the course of the next few centuries the dragons grew more and more fond of their subjects creating a tight bond with the mortals of the land. Many draconic sorcerer families are born and rise to great status."}),"\n",(0,o.jsx)(t.p,{children:"In the fall of the great dragon empire the land was shattered and splintered amongst decedents."}),"\n",(0,o.jsx)(t.p,{children:"Two of the eldest (oldest was a woman but first born boy was second oldest so both have claims in their eyes) bordered each other and warred for centuries and turned towards malevolent means for fighting"}),"\n",(0,o.jsx)(t.p,{children:"One sibling ruled a nation of undead the other ruled a nation of robots two everlasting servants of war."})]})}function c(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},8453(e,t,n){n.d(t,{R:()=>i,x:()=>h});var r=n(6540);let o={},a=r.createContext(o);function i(e){let t=r.useContext(a);return r.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function h(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),r.createElement(a.Provider,{value:t},e.children)}}}]);